<template>
  <div class="card">
    <!-- Шапка -->
    <div class="card-head">
      <div>
        <div class="card-tag">{{ $t('summary.pulse') }}</div>
        <h2 class="card-title">{{ customTitle || $t('summary.title') }}</h2>
        <p class="card-sub">{{ period }}</p>
      </div>
      <div class="score-wrap">
        <div class="score" :style="{ color: scoreColor }">
          {{ score }}<span class="score-sign">%</span>
        </div>
        <div class="score-label">{{ $t('summary.revenue') }}</div>
      </div>
    </div>

    <!-- Метрики -->
    <div class="metrics">
      <div
          v-for="m in metrics"
          :key="m.key"
          class="metric-row"
      >
        <div class="metric-left">
          <span class="metric-icon">{{ m.icon }}</span>
          <span class="metric-name">{{ m.name }}</span>
        </div>
        <div class="badges-pair">
          <span class="badge" :class="m.planClass">
            {{ m.planPct >= 100 ? '▲' : '▼' }} {{ m.planPct }}% {{ $t('common.plan') }}
          </span>
          <span class="badge" :class="m.yoyClass" v-if="!m.noYoy">
            {{ m.yoy >= 0 ? '▲ +' : '▼ ' }}{{ m.yoy }}% {{ $t('common.toLastYear') }}
          </span>
          <span class="badge yellow" v-else-if="m.noYoyText">{{ $t('metrics.monoNoData') }}</span>
          <span class="badge gray" v-else>—</span>
        </div>
      </div>
    </div>

    <div class="divider"></div>

    <!-- Итоги -->
    <div class="summary-row">
      <span class="summary-label">✅ {{ $t('summary.onPlan') }}</span>
      <span class="summary-val green">{{ onPlan }} {{ $t('summary.of') }} {{ metrics.length }}</span>
    </div>
    <div class="summary-row">
      <span class="summary-label">📈 {{ $t('summary.growing') }}</span>
      <span class="summary-val green">{{ growing }} {{ $t('summary.of') }} {{ yoyMetricsCount }}</span>
    </div>
    <div class="summary-row">
      <span class="summary-label">📉 {{ $t('summary.falling') }}</span>
      <span class="summary-val red">{{ falling }} {{ $t('summary.of') }} {{ yoyMetricsCount }}</span>
    </div>
  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'

function pctClass(p) {
  if (p >= 100) return 'green'
  if (p >= 85)  return 'yellow'
  return 'red'
}

function yoyClass(p) {
  return p >= 0 ? 'green' : 'red'
}

export default {
  name: 'SummaryCardComponent',

  props: {
    selectedDate: {
      type:    String,
      default: '',
    },
    rowData: {
      type:    Object,
      default: null,
    },
    customTitle: {
      type:    String,
      default: '',
    },
  },

  data() {
    return {
      metrics: [],
      period:  '',
    }
  },

  mounted() {
    this.setData()
  },

  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal && !this.rowData) this.setData()
    },
    rowData: {
      handler(val) { if (val) this.setData() },
      immediate: false,
    },
    '$i18n.locale'() {
      this.setData()
    },
  },

  computed: {
    score() {
      const products = this.metrics.find(m => m.key === 'products')
      return products ? products.planPct : 0
    },

    scoreColor() {
      if (this.score >= 100) return '#16a34a'
      if (this.score >= 85)  return '#d97706'
      return '#dc2626'
    },

    onPlan()  { return this.metrics.filter(m => m.planPct >= 100).length },
    growing() { return this.metrics.filter(m => !m.noYoy && m.yoy >= 0).length },
    falling() { return this.metrics.filter(m => !m.noYoy && m.yoy < 0).length },
    yoyMetricsCount() { return this.metrics.filter(m => !m.noYoy).length },
  },

  methods: {
    setData() {
      const row = this.rowData || (() => {
        const payload = dataStore.getCompanyData()
        if (!payload) return null
        return this.selectedDate
            ? payload.find(item => item.time === this.selectedDate)
            : payload[0]
      })()

      if (!row) return

      this.period = row.time

      const defs = [
        { key: 'products',   name: this.$t('metrics.revenue'),    icon: '💰', f: Number(row.products_f)   || 0, p: Number(row.products_p)   || 0, past: Number(row.products_past)   || 0 },
        { key: 'no_iphone',  name: this.$t('metrics.no_iphone'),  icon: '📵', f: Number(row.no_iphone_f)  || 0, p: Number(row.no_iphone_p)  || 0, past: Number(row.no_iphone_past) || 0 },
        { key: 'services',   name: this.$t('metrics.services'),   icon: '🛡️', f: Number(row.services_f)   || 0, p: Number(row.services_p)   || 0, past: Number(row.services_past)   || 0 },
        { key: 'trafic',     name: this.$t('metrics.trafic'),     icon: '👥', f: Number(row.trafic_f)     || 0, p: Number(row.trafic_p)     || 0, past: Number(row.trafic_past)     || 0 },
        { key: 'conver',     name: this.$t('metrics.conversion'), icon: '🎯', f: Number(row.conver_f)     || 0, p: Number(row.conver_p)     || 0, past: Number(row.conver_past)     || 0 },
        { key: 'check',      name: this.$t('metrics.check'),      icon: '🧾', f: Number(row.check_f)      || 0, p: Number(row.check_p)      || 0, past: Number(row.check_past)      || 0 },
        { key: 'count',      name: this.$t('metrics.count'),      icon: '📦', f: Number(row.count_f)      || 0, p: Number(row.count_p)      || 0, past: Number(row.count_past)      || 0 },
        // credit_past не существует в API — YoY для кредита не считается
        { key: 'credit',     name: this.$t('metrics.credit'),     icon: '💳', f: Number(row.credit_f)     || 0, p: Number(row.credit_p)     || 0, past: 0, noYoy: true },
      ]

      // im и mono добавляем только если есть данные (только компания, не менеджеры)
      const imF = Number(row.im_f) || 0
      const imP = Number(row.im_p) || 0
      if (imF > 0 || imP > 0) {
        defs.push({ key: 'im', name: this.$t('metrics.im'), icon: '🛒', f: imF, p: imP, past: Number(row.im_past) || 0 })
      }
      const monoF = Number(row.mono_f) || 0
      const monoP = Number(row.mono_p) || 0
      if (monoF > 0 || monoP > 0) {
        const monoHasPast = !!(Number(row.mono_past) || 0)
        defs.push({ key: 'mono', name: this.$t('metrics.mono'), icon: '🏪', f: monoF, p: monoP, past: Number(row.mono_past) || 0, noYoy: !monoHasPast, noYoyText: !monoHasPast })
      }

      this.metrics = defs.map(m => {
        const planPct = m.p ? Math.round((m.f / m.p) * 1000) / 10 : 0
        const yoy     = m.past ? Math.round(((m.f - m.past) / m.past) * 100) : 0
        return {
          ...m,
          planPct,
          yoy,
          planClass: pctClass(planPct),
          yoyClass:  yoyClass(yoy),
        }
      })
    },
  },
}
</script>

