<template>
  <div class="sp-wrap">

    <div class="sp-header">
      <div class="sp-tag">{{ $t('supProd.tag') }}</div>
      <h2 class="sp-section-title">{{ sectionTitle || $t('supProd.sectionTitle') }}</h2>
      <p class="sp-period">{{ period }}</p>
    </div>

    <div class="sp-cards">
      <div v-for="m in metrics" :key="m.key" class="sp-card">
        <div class="sp-card-bar" :style="{ background: m.color }"></div>
        <div class="sp-card-inner">
          <div class="sp-icon-wrap" :style="{ background: m.color + '18' }">
            <span class="sp-icon">{{ m.icon }}</span>
          </div>
          <div class="sp-card-label">{{ m.label }}</div>
          <div class="sp-card-val" :style="{ color: m.color }">
            {{ fmt(m.value) }}<span class="sp-pct">%</span>
          </div>
          <div class="sp-track">
            <div
                class="sp-track-fill"
                :style="{ width: trackWidth(m.value), background: m.color }"
            ></div>
          </div>
        </div>
      </div>
    </div>

  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'

export default {
  name: 'SupProdCards',

  props: {
    rowData:      { type: Object, default: null },
    selectedDate: { type: String, default: '' },
    sectionTitle: { type: String, default: '' },
  },

  computed: {
    row() {
      if (this.rowData) return this.rowData
      const payload = dataStore.getCompanyData()
      if (!payload) return null
      return this.selectedDate
          ? payload.find(r => r.time === this.selectedDate) || null
          : payload[0] || null
    },

    period() {
      return this.row?.time || ''
    },

    metrics() {
      const r = this.row
      return [
        { key: 'smart',    icon: '📱', color: '#6366f1', label: this.$t('supProd.smart'),    value: r?.smart    ?? 0 },
        { key: 'note',     icon: '💻', color: '#f59e0b', label: this.$t('supProd.note'),     value: r?.note     ?? 0 },
        { key: 'tv',       icon: '📺', color: '#14b8a6', label: this.$t('supProd.tv'),       value: r?.tv       ?? 0 },
        { key: 'sup_prod', icon: '🛍️', color: '#22c55e', label: this.$t('supProd.supProd'),  value: r?.sup_prod ?? 0 },
        { key: 'poslug',   icon: '🛡️', color: '#ec4899', label: this.$t('supProd.poslug'),   value: r?.poslug   ?? 0 },
      ]
    },
  },

  watch: {
    '$i18n.locale'() { /* metrics is reactive computed — обновляется автоматически */ },
  },

  methods: {
    fmt(val) {
      if (val == null || val === 0) return '0'
      return Number(val).toFixed(1).replace('.', ',')
    },
    trackWidth(val) {
      return Math.min(Number(val) || 0, 100) + '%'
    },
  },
}
</script>

